def suggest_type(full_text, text_before_cursor):
    """Takes the full_text that is typed so far and also the text before the
    cursor to suggest completion type and scope.

    Returns a tuple with a type of entity ('table', 'column' etc) and a scope.
    A scope for a column category will be a list of tables.
    """

    if full_text.startswith('\\i '):
        return (Path(),)

    # This is a temporary hack; the exception handling
    # here should be removed once sqlparse has been fixed
    try:
        stmt = SqlStatement(full_text, text_before_cursor)
    except (TypeError, AttributeError):
        return []

    # Check for special commands and handle those separately
    if stmt.parsed:
        # Be careful here because trivial whitespace is parsed as a
        # statement, but the statement won't have a first token
        tok1 = stmt.parsed.token_first()
        if tok1 and tok1.value == '\\':
            text = stmt.text_before_cursor + stmt.word_before_cursor
            return suggest_special(text)

    return suggest_based_on_last_token(stmt.last_token, stmt)

def format_array(val):
    if val is None:
        return settings.missingval
    if not isinstance(val, list):
        return val
    return '{' + ','.join(text_type(format_array(e)) for e in val) + '}'

def format_arrays(data, headers, **_):
    data = list(data)
    for row in data:
        row[:] = [
            format_array(val) if isinstance(val, list) else val
            for val in row
        ]

    return data, headers

def __repr__(self):
    return (
        (
            '%s(schema_name=%r, func_name=%r, arg_names=%r, '
            'arg_types=%r, arg_modes=%r, return_type=%r, is_aggregate=%r, '
            'is_window=%r, is_set_returning=%r, arg_defaults=%r)'
        ) % (self.__class__.__name__, self.schema_name, self.func_name, self.arg_names,
             self.arg_types, self.arg_modes, self.return_type, self.is_aggregate,
             self.is_window, self.is_set_returning, self.arg_defaults)
    )

def send(self, data_to_send):
    """
        Override the send method to strip the request_payload's brackets since Vortex does not.
    """
    request_payload = json.dumps([a.write() for a in data_to_send]).strip('[').strip(']')

    request = HTTPClient.Request(self._service_endpoint_uri,
                                 bytearray(request_payload, 'utf-8'),
                                 {'Accept': 'application/json',
                                  'Content-Type': 'application/json; charset=utf-8'})
    try:
        response = HTTPClient.urlopen(request, timeout=self._timeout)
        status_code = response.getcode()
        if 200 <= status_code < 300:
            if in_diagnostic_mode():
                print('Telemetry uploaded succesfully.')
            return
    except HTTPError as e:
        if e.getcode() == 400:
            raise e
    except (AttributeError, ValueError, URLError):
        if self.retry < 3:
            self.retry += 1
        else:
            return

    # Add our unsent data back on to the queue
    for data in data_to_send:
        self._queue.put(data)

def upload(data_to_save, service_endpoint_uri):

    client = build_vortex_telemetry_client(service_endpoint_uri)

    if in_diagnostic_mode():
        sys.stdout.write('Telemetry upload begins\n')
        sys.stdout.write('Got data {}\n'.format(json.dumps(json.loads(data_to_save), indent=2)))

    try:
        data_to_save = json.loads(data_to_save.replace("'", '"'))
    except Exception as err:  # pylint: disable=broad-except
        if in_diagnostic_mode():
            sys.stdout.write('{}/n'.format(str(err)))
            sys.stdout.write('Raw [{}]/n'.format(data_to_save))

    for record in data_to_save:
        name = record['name']
        raw_properties = record['properties']
        properties = {}
        measurements = {}
        for k in raw_properties:
            v = raw_properties[k]

            # pylint: disable=undefined-variable
            # suppress warning for undefined variable, since `basestring` was dropped in python 3
            if isinstance(v, str if sys.version_info[0] >= 3 else basestring):
                properties[k] = v
            else:
                measurements[k] = v
        client.track_event(name, properties, measurements)

    try:
        client.flush()
        if in_diagnostic_mode():
            sys.stdout.write('\nTelemetry upload completes\n')

    except HTTPError as e:
        if in_diagnostic_mode():
            raise e

def conclude(service_endpoint_uri='https://vortex.data.microsoft.com/collect/v1',
             separate_process=True):
    _session.end_time = datetime.now()

    payload = _session.generate_payload()
    output_payload_to_file(payload)
    return upload_payload(payload, service_endpoint_uri, separate_process)

def upload_payload(payload, service_endpoint_uri, separate_process):
    payload_uploaded = None
    if payload:
        if not separate_process:
            telemetry_core.upload(payload, service_endpoint_uri)
        else:
            subprocess.Popen([sys.executable, os.path.realpath(telemetry_core.__file__),
                              payload, service_endpoint_uri])
        payload_uploaded = payload
    return payload_uploaded

