    for pair in pairs:
        d[pair[0]].append(pair[1])
    return d

def _compile_regex(keyword):
    # Surround the keyword with word boundaries and replace interior whitespace
    # with whitespace wildcards
    pattern = '\\b' + white_space_regex.sub(r'\\s+', keyword) + '\\b'
    return re.compile(pattern, re.MULTILINE | re.IGNORECASE)

def response_error(cls, error):
    return QueryCompleteEvent(
        {u'params': None}, exception_message=str(error)
    )

def encode(s):
    try:
        return s.encode('utf-8')
    except (AttributeError, SyntaxError):
        pass
    return s

def decode(s):
    try:
        return s.decode('utf-8')
    except (AttributeError, SyntaxError, UnicodeEncodeError):
        pass
    return s

def unicode2utf8(arg):
    """
    Only in Python 2.
    In Python 3 the args are expected as unicode.
    """

    try:
        if isinstance(arg, unicode):
            return arg.encode('utf-8')
    except NameError:
        pass  # Python 3
    return arg

def utf8tounicode(arg):
    """
    Only in Python 2.
    In Python 3 the errors are returned as unicode.
    """

    try:
        if isinstance(arg, unicode):
            return arg.decode('utf-8')
    except NameError:
        pass  # Python 3
    return arg

def decode_response(response):
    result_subset = None

    if u'result' in response:
        result_subset = ResultSubset(response)
    elif u'error' in response:
        result_subset = ResultSubset(
            None, error_message=response[u'error']['message'])

    return result_subset

