def _statement_from_function(full_text, text_before_cursor, statement):
    current_pos = len(text_before_cursor)
    body_start, body_end = _find_function_body(full_text)
    if body_start is None:
        return full_text, text_before_cursor, statement
    if not body_start <= current_pos < body_end:
        return full_text, text_before_cursor, statement
    full_text = full_text[body_start:body_end]
    text_before_cursor = text_before_cursor[body_start:]
    parsed = sqlparse.parse(text_before_cursor)
    return _split_multiple_statements(full_text, text_before_cursor, parsed)

def _split_multiple_statements(full_text, text_before_cursor, parsed):
    if len(parsed) > 1:
        # Multiple statements being edited -- isolate the current one by
        # cumulatively summing statement lengths to find the one that bounds
        # the current position
        current_pos = len(text_before_cursor)
        stmt_start, stmt_end = 0, 0

        for statement in parsed:
            stmt_len = len(str(statement))
            stmt_start, stmt_end = stmt_end, stmt_end + stmt_len

            if stmt_end >= current_pos:
                text_before_cursor = full_text[stmt_start:current_pos]
                full_text = full_text[stmt_start:]
                break

    elif parsed:
        # A single statement
        statement = parsed[0]
    else:
        # The empty string
        return full_text, text_before_cursor, None

    token2 = None
    if statement.get_type() in ('CREATE', 'CREATE OR REPLACE'):
        token1 = statement.token_first()
        if token1:
            token1_idx = statement.token_index(token1)
            token2 = statement.token_next(token1_idx)[1]
    if token2 and token2.value.upper() == 'FUNCTION':
        full_text, text_before_cursor, statement = _statement_from_function(
            full_text, text_before_cursor, statement
        )
    return full_text, text_before_cursor, statement

def is_subselect(parsed):
    if not parsed.is_group:
        return False
    for item in parsed.tokens:
        if item.ttype is DML and item.value.upper() in ('SELECT', 'INSERT',
                                                        'UPDATE', 'CREATE', 'DELETE'):
            return True
    return False

def extract_from_part(parsed, stop_at_punctuation=True):
    tbl_prefix_seen = False
    for item in parsed.tokens:
        if tbl_prefix_seen:
            if is_subselect(item):
                for x in extract_from_part(item, stop_at_punctuation):
                    yield x
            elif stop_at_punctuation and item.ttype is Punctuation:
                # An incomplete nested select won't be recognized correctly as a
                # sub-select. eg: 'SELECT * FROM (SELECT id FROM user'. This causes
                # the second FROM to trigger this elif condition resulting in a
                # StopIteration. So we need to ignore the keyword if the keyword
                # FROM.
                # Also 'SELECT * FROM abc JOIN def' will trigger this elif
                # condition. So we need to ignore the keyword JOIN and its variants
                # INNER JOIN, FULL OUTER JOIN, etc.
                return
            elif item.ttype is Keyword and (
                    not item.value.upper() == 'FROM') and \
                    (not item.value.upper().endswith('JOIN')):
                tbl_prefix_seen = False
            else:
                yield item
        elif item.ttype is Keyword or item.ttype is Keyword.DML:
            item_val = item.value.upper()
            if (item_val in ('COPY', 'FROM', 'INTO', 'UPDATE', 'TABLE') or
                    item_val.endswith('JOIN')):
                tbl_prefix_seen = True
        # 'SELECT a, FROM abc' will detect FROM as part of the column list.
        # So this check here is necessary.
        elif isinstance(item, IdentifierList):
            for identifier in item.get_identifiers():
                if (identifier.ttype is Keyword and
                        identifier.value.upper() == 'FROM'):
                    tbl_prefix_seen = True
                    break

def suggest_based_on_last_token(token, stmt):

    if isinstance(token, string_types):
        token_v = token.lower()
    elif isinstance(token, Comparison):
        # If 'token' is a Comparison type such as
        # 'select * FROM abc a JOIN def d ON a.id = d.'. Then calling
        # token.value on the comparison type will only return the lhs of the
        # comparison. In this case a.id. So we need to do token.tokens to get
        # both sides of the comparison and pick the last token out of that
        # list.
        token_v = token.tokens[-1].value.lower()
    elif isinstance(token, Where):
        # sqlparse groups all tokens from the where clause into a single token
        # list. This means that token.value may be something like
        # 'where foo > 5 and '. We need to look "inside" token.tokens to handle
        # suggestions in complicated where clauses correctly
        prev_keyword = stmt.reduce_to_prev_keyword()
        return suggest_based_on_last_token(prev_keyword, stmt)
    elif isinstance(token, Identifier):
        # If the previous token is an identifier, we can suggest datatypes if
        # we're in a parenthesized column/field list, e.g.:
        #       CREATE TABLE foo (Identifier <CURSOR>
        #       CREATE FUNCTION foo (Identifier <CURSOR>
        # If we're not in a parenthesized list, the most likely scenario is the
        # user is about to specify an alias, e.g.:
        #       SELECT Identifier <CURSOR>
        #       SELECT foo FROM Identifier <CURSOR>
        prev_keyword, _ = find_prev_keyword(stmt.text_before_cursor)
        if prev_keyword and prev_keyword.value == '(':
            # Suggest datatypes
            return suggest_based_on_last_token('type', stmt)
        return (Keyword(),)
    else:
        token_v = token.value.lower()

    if not token:
        return (Keyword(), Special())
    if token_v.endswith('('):
        p = sqlparse.parse(stmt.text_before_cursor)[0]

        if p.tokens and isinstance(p.tokens[-1], Where):
            # Four possibilities:
            #  1 - Parenthesized clause like "WHERE foo AND ("
            #        Suggest columns/functions
            #  2 - Function call like "WHERE foo("
            #        Suggest columns/functions
            #  3 - Subquery expression like "WHERE EXISTS ("
            #        Suggest keywords, in order to do a subquery
            #  4 - Subquery OR array comparison like "WHERE foo = ANY("
            #        Suggest columns/functions AND keywords. (If we wanted to be
            #        really fancy, we could suggest only array-typed columns)

            column_suggestions = suggest_based_on_last_token('where', stmt)

            # Check for a subquery expression (cases 3 & 4)
            where = p.tokens[-1]
            prev_tok = where.token_prev(len(where.tokens) - 1)[1]

            if isinstance(prev_tok, Comparison):
                # e.g. "SELECT foo FROM bar WHERE foo = ANY("
                prev_tok = prev_tok.tokens[-1]

            prev_tok = prev_tok.value.lower()
            if prev_tok == 'exists':
                return (Keyword(),)
            return column_suggestions

        # Get the token before the parens
        prev_tok = p.token_prev(len(p.tokens) - 1)[1]

        if (prev_tok and prev_tok.value and prev_tok.value.lower().split(' ')[-1] == 'using'):
            # tbl1 INNER JOIN tbl2 USING (col1, col2)
            tables = stmt.get_tables('before')

            # suggest columns that are present in more than one table
            return (Column(table_refs=tables,
                           require_last_table=True,
                           local_tables=stmt.local_tables),)

        if p.token_first().value.lower() == 'select':
            # If the lparen is preceeded by a space chances are we're about to
            # do a sub-select.
            if last_word(stmt.text_before_cursor,
                         'all_punctuations').startswith('('):
                return (Keyword(),)
        prev_prev_tok = prev_tok and p.token_prev(p.token_index(prev_tok))[1]
        if prev_prev_tok and prev_prev_tok.normalized == 'INTO':
            return (
                Column(table_refs=stmt.get_tables('insert'), context='insert'),
            )
        # We're probably in a function argument list
        return (Column(table_refs=extract_tables(stmt.full_text),
                       local_tables=stmt.local_tables, qualifiable=True),)
    if token_v == 'set':
        return (Column(table_refs=stmt.get_tables(),
                       local_tables=stmt.local_tables),)
    if token_v in ('select', 'where', 'having', 'by', 'distinct'):
        # Check for a table alias or schema qualification
        parent = stmt.identifier.get_parent_name() \
            if (stmt.identifier and stmt.identifier.get_parent_name()) else []
        tables = stmt.get_tables()
        if parent:
            tables = tuple(t for t in tables if identifies(parent, t))
            return (Column(table_refs=tables, local_tables=stmt.local_tables),
                    Table(schema=parent),
                    View(schema=parent),
                    Function(schema=parent),)
        return (Column(table_refs=tables, local_tables=stmt.local_tables,
                       qualifiable=True),
                Function(schema=None),
                Keyword(token_v.upper()),)
    if token_v == 'as':
        # Don't suggest anything for aliases
        return ()
    if (token_v.endswith('join') and token.is_keyword) or \
         token_v in ('copy', 'from', 'update', 'into', 'describe', 'truncate'):

        schema = stmt.get_identifier_schema()
        tables = extract_tables(stmt.text_before_cursor)
        is_join = token_v.endswith('join') and token.is_keyword

        # Suggest tables from either the currently-selected schema or the
        # public schema if no schema has been specified
        suggest = []

        if not schema:
            # Suggest schemas
            suggest.insert(0, Schema())

        if token_v == 'from' or is_join:
            suggest.append(FromClauseItem(schema=schema,
                                          table_refs=tables,
                                          local_tables=stmt.local_tables))
        elif token_v == 'truncate':
            suggest.append(Table(schema))
        else:
            suggest.extend((Table(schema), View(schema)))

        if is_join and _allow_join(stmt.parsed):
            tables = stmt.get_tables('before')
            suggest.append(Join(table_refs=tables, schema=schema))

        return tuple(suggest)

    if token_v == 'function':
        schema = stmt.get_identifier_schema()
        # stmt.get_previous_token will fail for e.g. `SELECT 1 FROM functions
        # WHERE function:`
        try:
            prev = stmt.get_previous_token(token).value.lower()
            if prev in('drop', 'alter', 'create', 'create or replace'):
                return (Function(schema=schema, usage='signature'),)
        except ValueError:
            pass
        return tuple()

    if token_v in ('table', 'view'):
        # E.g. 'ALTER TABLE <tablname>'
        rel_type = {
            'table': Table,
            'view': View,
            'function': Function}[token_v]
        schema = stmt.get_identifier_schema()
        if schema:
            return (rel_type(schema=schema),)
        return (Schema(), rel_type(schema=schema))

    if token_v == 'column':
        # E.g. 'ALTER TABLE foo ALTER COLUMN bar
        return (Column(table_refs=stmt.get_tables()),)

    if token_v == 'on':
        tables = stmt.get_tables('before')
        parent = stmt.identifier.get_parent_name() \
            if (stmt.identifier and stmt.identifier.get_parent_name()) else None
        if parent:
            # "ON parent.<suggestion>"
            # parent can be either a schema name or table alias
            filteredtables = tuple(t for t in tables if identifies(parent, t))
            sugs = [Column(table_refs=filteredtables,
                           local_tables=stmt.local_tables),
                    Table(schema=parent),
                    View(schema=parent),
                    Function(schema=parent)]
            if filteredtables and _allow_join_condition(stmt.parsed):
                sugs.append(JoinCondition(table_refs=tables,
                                          parent=filteredtables[-1]))
            return tuple(sugs)
        # ON <suggestion>
        # Use table alias if there is one, otherwise the table name
        aliases = tuple(t.ref for t in tables)
        if _allow_join_condition(stmt.parsed):
            return (Alias(aliases=aliases), JoinCondition(
                table_refs=tables, parent=None))
        return (Alias(aliases=aliases),)

    if token_v in ('c', 'use', 'database', 'template'):
        # "\c <db", "use <db>", "DROP DATABASE <db>",
        # "CREATE DATABASE <newdb> WITH TEMPLATE <db>"
        return (Database(),)
    if token_v == 'schema':
        # DROP SCHEMA schema_name, SET SCHEMA schema name
        prev_keyword = stmt.reduce_to_prev_keyword(n_skip=2)
        quoted = prev_keyword and prev_keyword.value.lower() == 'set'
        return (Schema(quoted),)
    if token_v.endswith(',') or token_v in ('=', 'and', 'or'):
        prev_keyword = stmt.reduce_to_prev_keyword()
        if prev_keyword:
            return suggest_based_on_last_token(prev_keyword, stmt)
        return ()
    if token_v in ('type', '::'):
        #   ALTER TABLE foo SET DATA TYPE bar
        #   SELECT foo::bar
        # Note that tables are a form of composite type in postgresql, so
        # they're suggested here as well
        schema = stmt.get_identifier_schema()
        suggestions = [Datatype(schema=schema),
                       Table(schema=schema)]
        if not schema:
            suggestions.append(Schema())
        return tuple(suggestions)
    if token_v in {'alter', 'create', 'drop'}:
        return (Keyword(token_v.upper()),)
    if token.is_keyword:
        # token is a keyword we haven't implemented any special handling for
        # go backwards in the query until we find one we do recognize
        prev_keyword = stmt.reduce_to_prev_keyword(n_skip=1)
        if prev_keyword:
            return suggest_based_on_last_token(prev_keyword, stmt)
        return (Keyword(token_v.upper()),)
    return (Keyword(),)

def identifies(string_id, ref):
    """Returns true if string `string_id` matches TableReference `ref`"""

    return string_id == ref.alias or string_id == ref.name or (
        ref.schema and (string_id == ref.schema + '.' + ref.name))

def _find_function_body(text):
    split = function_body_pattern.search(text)
    return (split.start(2), split.end(2)) if split else (None, None)

def suggest_special(text):
    text = text.lstrip()
    cmd, _, arg = parse_special_command(text)

    if cmd == text:
        # Trying to complete the special command itself
        return (Special(),)

    if cmd in ('\\c', '\\connect'):
        return (Database(),)

    if cmd == '\\ls':
        return (Schema(),)

    if arg:
        # Try to distinguish "\d name" from "\d schema.name"
        # Note that this will fail to obtain a schema name if wildcards are
        # used, e.g. "\d schema???.name"
        parsed = sqlparse.parse(arg)[0].tokens[0]
        try:
            schema = parsed.get_parent_name()
        except AttributeError:
            schema = None
    else:
        schema = None

    if cmd[1:] == 'd':
        # \d can describe tables or views
        if schema:
            return (Table(schema=schema),
                    View(schema=schema),)
        return (Schema(),
                Table(schema=None),
                View(schema=None),)
    if cmd[1:] in SPECIALS_SUGGESTION:
        rel_type = SPECIALS_SUGGESTION[cmd[1:]]
        if schema:
            if rel_type == Function:
                return (Function(schema=schema, usage='special'),)
            return (rel_type(schema=schema),)
        if rel_type == Function:
            return (Schema(), Function(schema=None, usage='special'),)
        return (Schema(), rel_type(schema=None))

    if cmd in ['\\n', '\\sn', '\\dn']:
        return (NamedQuery(),)

    return (Keyword(), Special())

def parse_special_command(sql):
    command, _, arg = sql.partition(' ')
    verbose = '+' in command
    command = command.strip().replace('+', '')
    return (command, verbose, arg.strip())

def execute(mssqlcliclient, sql):
    """Execute a special command and return the results. If the special command
    is not supported a KeyError will be raised.
    """
    command, verbose, pattern = parse_special_command(sql)

    if (command not in COMMANDS) and (command.lower() not in COMMANDS):
        raise CommandNotFound('Command not found: %s' % command)

    try:
        special_cmd = COMMANDS[command]
    except KeyError:
        special_cmd = COMMANDS[command.lower()]
        if special_cmd.case_sensitive:
            raise CommandNotFound('Command not found: %s' % command)

    logger.debug(u'Executing special command %s with argument %s.', command, pattern)

    if special_cmd.arg_type == NO_QUERY:
        return special_cmd.handler()
    if special_cmd.arg_type == PARSED_QUERY:
        return special_cmd.handler(mssqlcliclient=mssqlcliclient, pattern=pattern, verbose=verbose)
    if special_cmd.arg_type == RAW_QUERY:
        return special_cmd.handler(mssqlcliclient=mssqlcliclient, query=sql)

    return None

def get_watch_command(command):
    match = re.match(r'(.*?)[\s]*\\\\watch (\d+);?$', command)
    if match:
        groups = match.groups()
        return groups[0], int(groups[1])
    return None, None

def get_literals(literal_type, type_=tuple):
    # Where `literal_type` is one of 'keywords', 'functions', 'datatypes',
    # returns a tuple of literal values of that type.

    return type_(literals[literal_type])

def format(self):
    return {u'OwnerUri': self.owner_uri,
            u'Connection': self.connection_details.format()}

def format(self):
    return {u'OwnerUri': self.owner_uri,
            u'Query': self.query}

def args(self):
    """Returns a list of input-parameter ColumnMetadata namedtuples."""
    if not self.arg_names:
        return []
    modes = self.arg_modes or ['i'] * len(self.arg_names)
    args = [
        (name, typ)
        for name, typ, mode in zip(self.arg_names, self.arg_types, modes)
        if mode in ('i', 'b', 'v')  # IN, INOUT, VARIADIC
    ]

    def arg(name, typ, num):
        num_args = len(args)
        num_defaults = len(self.arg_defaults)
        has_default = num + num_defaults >= num_args
        default = (
            self.arg_defaults[num - num_args + num_defaults] if has_default
            else None
        )
        return ColumnMetadata(name, typ, [], default, has_default)

    return [arg(name, typ, num) for num, (name, typ) in enumerate(args)]

def fields(self):
    """Returns a list of output-field ColumnMetadata namedtuples"""

    if self.return_type.lower() == 'void':
        return []
    if not self.arg_modes:
        # For functions  without output parameters, the function name
        # is used as the name of the output column.
        # E.g. 'SELECT unnest FROM unnest(...);'
        return [ColumnMetadata(self.func_name, self.return_type, [])]

    return [ColumnMetadata(name, typ, [])
            for name, typ, mode in zip(
                self.arg_names, self.arg_types, self.arg_modes)
            if mode in ('o', 'b', 't')]  # OUT, INOUT, TABLE

def arg(name, typ, num):
    num_args = len(args)
    num_defaults = len(self.arg_defaults)
    has_default = num + num_defaults >= num_args
    default = (
        self.arg_defaults[num - num_args + num_defaults] if has_default
        else None
    )
    return ColumnMetadata(name, typ, [], default, has_default)

def parse_defaults(defaults_string):
    """
    Yields default values for a function, given the string provided.
    """
    if not defaults_string:
        return
    current = ''
    in_quote = None
    for char in defaults_string:
        if current == '' and char == ' ':
            # Skip space after comma separating default expressions
            continue
        if char in ('"', '\''):
            if in_quote and char == in_quote:
                # End quote
                in_quote = None
            elif not in_quote:
                # Begin quote
                in_quote = char
        elif char == ',' and not in_quote:
            # End of expression
            yield current
            current = ''
            continue
        current += char
    yield current

def __init__(
        self, schema_name, func_name, arg_names, arg_types, arg_modes,
        return_type, is_aggregate, is_window, is_set_returning, arg_defaults

def __init__(self, parameters):
    self.owner_uri = parameters['OwnerUri']
    self.query = parameters['Query']

def __init__(self, parameters, exception_message=None):
    inner_params = parameters[u'params']
    if inner_params:
        self.owner_uri = inner_params[u'ownerUri']
        self.batch_summaries = []
        for batch_summary in inner_params[u'batchSummaries']:
            self.batch_summaries.append(BatchSummary(batch_summary))

    self.exception_message = exception_message

def __init__(self, parameters, error_message=None):
    if not error_message:
        inner_params = parameters[u'result'][u'resultSubset']
        self.row_count = inner_params[u'rowCount']
        self.rows = []
        for row in inner_params[u'rows']:
            self.rows.append(ResultRow(row))

    self.error_message = error_message

def _signature(self):
    return (
        self.schema_name, self.func_name, self.arg_names, self.arg_types,
        self.arg_modes, self.return_type, self.is_aggregate,
        self.is_window, self.is_set_returning, self.arg_defaults
    )

def extract_table_identifiers(token_stream, allow_functions=True):
    """yields tuples of TableReference namedtuples"""

    # We need to do some massaging of the names because postgres is case-
    # insensitive and '"Foo"' is not the same table as 'Foo' (while 'foo' is)
    def parse_identifier(item):
        name = item.get_real_name()
        schema_name = item.get_parent_name()
        alias = item.get_alias()
        if not name:
            schema_name = None
            name = item.get_name()
            alias = alias or name
        schema_quoted = schema_name and item.value[0] == '"'
        if schema_name and not schema_quoted:
            schema_name = schema_name.lower()
        quote_count = item.value.count('"')
        name_quoted = quote_count > 2 or (quote_count and not schema_quoted)
        alias_quoted = alias and item.value[-1] == '"'
        if alias_quoted or name_quoted and not alias and name.islower():
            alias = '"' + (alias or name) + '"'
        if name and not name_quoted and not name.islower():
            if not alias:
                alias = name
            name = name.lower()
        return schema_name, name, alias

    for item in token_stream:
        if isinstance(item, IdentifierList):
            for identifier in item.get_identifiers():
                # Sometimes Keywords (such as FROM ) are classified as
                # identifiers which don't have the get_real_name() method.
                try:
                    schema_name = identifier.get_parent_name()
                    real_name = identifier.get_real_name()
                    is_function = (allow_functions and
                                   _identifier_is_function(identifier))
                except AttributeError:
                    continue
                if real_name:
                    yield TableReference(schema_name, real_name,
                                         identifier.get_alias(), is_function)
        elif isinstance(item, Identifier):
            schema_name, real_name, alias = parse_identifier(item)
            is_function = allow_functions and _identifier_is_function(item)

            yield TableReference(schema_name, real_name, alias, is_function)
        elif isinstance(item, Function):
            schema_name, real_name, alias = parse_identifier(item)
            yield TableReference(None, real_name, alias, allow_functions)

def isolate_query_ctes(full_text, text_before_cursor):
    """Simplify a query by converting CTEs into table metadata objects
    """

    if not full_text:
        return full_text, text_before_cursor, tuple()

    ctes, _ = extract_ctes(full_text)
    if not ctes:
        return full_text, text_before_cursor, ()

    current_position = len(text_before_cursor)
    meta = []

    for cte in ctes:
        if cte.start < current_position < cte.stop:
            # Currently editing a cte - treat its body as the current full_text
            text_before_cursor = full_text[cte.start:current_position]
            full_text = full_text[cte.start:cte.stop]
            return full_text, text_before_cursor, meta

        # Append this cte to the list of available table metadata
        cols = (ColumnMetadata(name, None, ()) for name in cte.columns)
        meta.append(TableMetadata(cte.name, cols))

    # Editing past the last cte (ie the main body of the query)
    full_text = full_text[ctes[-1].stop:]
    text_before_cursor = text_before_cursor[ctes[-1].stop:current_position]

    return full_text, text_before_cursor, tuple(meta)

def get_cte_from_token(tok, pos0):
    cte_name = tok.get_real_name()
    if not cte_name:
        return None

    # Find the start position of the opening parens enclosing the cte body
    idx, parens = tok.token_next_by(Parenthesis)
    if not parens:
        return None

    start_pos = pos0 + token_start_pos(tok.tokens, idx)
    cte_len = len(str(parens))  # includes parens
    stop_pos = start_pos + cte_len

    column_names = extract_column_names(parens)

    return TableExpression(cte_name, column_names, start_pos, stop_pos)

def extract_column_names(parsed):
    # Find the first DML token to check if it's a SELECT or INSERT/UPDATE/DELETE
    idx, tok = parsed.token_next_by(t=DML)
    tok_val = tok and tok.value.lower()

    if tok_val in ('insert', 'update', 'delete'):
        # Jump ahead to the RETURNING clause where the list of column names is
        idx, tok = parsed.token_next_by(idx, (Keyword, 'returning'))
    elif not tok_val == 'select':
        # Must be invalid CTE
        return ()

    # The next token should be either a column name, or a list of column names
    idx, tok = parsed.token_next(idx, skip_ws=True, skip_cm=True)
    return tuple(t.get_name() for t in _identifiers(tok))

def _identifiers(tok):
    if isinstance(tok, IdentifierList):
        for t in tok.get_identifiers():
            # NB: IdentifierList.get_identifiers() can return non-identifiers!
            if isinstance(t, Identifier):
                yield t
    elif isinstance(tok, Identifier):
        yield tok

def execute_named_query(mssqlcliclient, pattern, **__):
    if pattern == '':
        return list_named_queries(True)

    params = shlex.split(pattern)
    pattern = params.pop(0)

    query = named_queries.get(pattern)
    if query is None:
        message = "No named query: {}".format(pattern)
        return [(None, None, message, None, False)]
    query, arg_error = subst_favorite_query_args(query, params)
    if arg_error:
        return [(None, None, arg_error, None, False)]
    return mssqlcliclient.execute_query(query)

def list_named_queries(verbose):
    """List of all named queries.
    Returns (rows, cols, status, sql, is_error)"""
    if not verbose:
        rows = [[r] for r in named_queries.list()]
        headers = ["Name"]
    else:
        headers = ["Name", "Query"]
        rows = [[r, named_queries.get(r)]
                for r in named_queries.list()]

    if not rows:
        status = named_queries.usage
    else:
        status = ''
    return [(rows, headers, status, '', False)]

def subst_favorite_query_args(query, args):
    """replace positional parameters ($1...$N) in query."""
    for idx, val in enumerate(args):
        subst_var = '$' + str(idx + 1)
        if subst_var not in query:
            return [None, 'query does not have substitution parameter ' + subst_var + ':\n  ' \
                                                                        + query]

        query = query.replace(subst_var, val)
    match = re.search('\\$\d+', query)
    if match:
        return[None, 'missing substitution for ' + match.group(0) + ' in query:\n  ' + query]

    return [query, None]

def get_response(self, request_id=0, owner_uri=0):
    """
        Get latest response. Priority order: Response, Event, Exception.
    """
    if request_id in self.response_map:
        if not self.response_map[request_id].empty():
            return self.response_map[request_id].get()

    if owner_uri in self.response_map:
        if not self.response_map[owner_uri].empty():
            return self.response_map[owner_uri].get()

    if not self.response_map[0].empty():
        return self.response_map[0].get()

    if not self.exception_queue.empty():
        raise self.exception_queue.get()

    return None

def save(self, name, query):
    if self.section_name not in self.config:
        self.config[self.section_name] = {}
    self.config[self.section_name][name] = query
    self.config.write()

def delete(self, name):
    try:
        del self.config[self.section_name][name]
    except KeyError:
        return '%s: Not Found.' % name
    self.config.write()
    return '%s: Deleted' % name

def close(self):
    """
        Close the stream.
    """
    try:
        self.stream.close()
    except AttributeError:
        pass

def close(self):
    """
        Close the stream.
    """
    try:
        self.stream.close()
    except AttributeError:
        pass

def list_views(mssqlcliclient, pattern, verbose):
    pattern = pattern.replace('"', '').split('.')[-1]
    base_query = u'select {0} from INFORMATION_SCHEMA.TABLES WHERE TABLE_TYPE=\'VIEW\''
    if verbose:
        base_query = base_query.format('table_catalog as catalog, table_schema as schema_name, '
                                       'table_name as view_name')
    else:
        base_query = base_query.format('table_schema as schema_name, table_name as view_name')
    if pattern:
        base_query += "and table_name like '%{0}%'".format(pattern)

    return mssqlcliclient.execute_query(base_query)

def describe_object(mssqlcliclient, pattern, verbose):
    if not pattern:
        click.secho('OBJECT is required. Usage \'\\d OBJECT\'.', err=True, fg='red')
        return []

    base_query = 'exec sp_help [{0}]'.format(pattern)
    return mssqlcliclient.execute_query(base_query)

def get_filename(sql):
    if sql.strip().startswith('\\e'):
        _, _, filename = sql.partition(' ')
        return filename.strip() or None
    return None

def __init__(self, parameters):
    # Required params
    self.ServerName = parameters[u'ServerName']
    self.DatabaseName = parameters[u'DatabaseName']
    self.UserName = parameters[u'UserName']
    self.Password = parameters[u'Password']
    self.AuthenticationType = parameters[u'AuthenticationType']
    # Optional Params
    if u'Encrypt' in parameters:
        self.Encrypt = parameters[u'Encrypt']
    if u'TrustServerCertificate' in parameters:
        self.TrustServerCertificate = parameters[u'TrustServerCertificate']
    if u'ConnectTimeout' in parameters:
        self.ConnectTimeout = parameters[u'ConnectTimeout']
    if u'ApplicationIntent' in parameters:
        self.ApplicationIntent = parameters[u'ApplicationIntent']
    if u'MultiSubnetFailover' in parameters:
        self.MultiSubnetFailover = parameters[u'MultiSubnetFailover']
    if u'PacketSize' in parameters:
        self.PacketSize = parameters[u'PacketSize']

def __init__(self, parameter):
    self.result_cells = []
    for result_cell in parameter:
        self.result_cells.append(ResultCell(result_cell))
